new_filter = r'''const synonymMap={fila:'queue broker rabbitmq kafka pubsub mensageria',queue:'fila broker rabbitmq kafka pubsub',erro:'error exception failure falha',falha:'failure error retry resilience',evento:'event message broker kafka pubsub',mensagem:'message event broker queue',bloqueio:'lock blocking event loop',concorrencia:'concurrency race lock atomic',transacao:'transaction acid database outbox',indice:'index btree database explain',container:'docker pod kubernetes',pod:'kubernetes container deployment',nuvem:'cloud gcp run gke functions',autenticacao:'authentication auth jwt oauth oidc',autorizacao:'authorization permission guard iam',teste:'test jest testing rtl e2e integration',cache:'redis ttl invalidation stampede',observabilidade:'observability logs metrics traces telemetry',microservico:'microservices distributed service',microservicos:'microservices distributed service',distribuido:'distributed messaging consistency retry idempotency',distribuidos:'distributed messaging consistency retry idempotency'};
function expandTerms(raw){const base=normalize(raw).split(/\s+/).filter(Boolean),out=[...base];base.forEach(t=>{if(synonymMap[t])out.push(...normalize(synonymMap[t]).split(/\s+/))});return [...new Set(out)]}
function filter(){const raw=document.getElementById('search').value,exact=normalize(raw),terms=expandTerms(raw);let n=0;const cards=[...document.querySelectorAll('.card')];cards.forEach(el=>{const hay=normalize(el.dataset.search),okCat=active==='Todos'||el.dataset.cat===active;let score=0;if(!exact)score=1;else{if(hay.includes(exact))score+=120;const title=normalize(el.querySelector('h2').textContent);if(title.includes(exact))score+=120;terms.forEach(t=>{if(title.includes(t))score+=28;if(hay.includes(t))score+=6})}const ok=okCat&&(!exact||score>0);el.classList.toggle('hidden',!ok);el.style.order=ok?-score:0;const badge=el.querySelector('.score');if(badge)badge.textContent=exact&&ok?`relevância ${score}`:'';if(ok)n++});document.getElementById('count').textContent=`${n}/${questions.length}`;document.getElementById('empty').style.display=n?'none':'block'}'''
